SELECT c.is_active, CASE WHEN c.credit_limit >= 16700 THEN 'high' WHEN c.credit_limit >= 2700 THEN 'mid' ELSE 'low' END AS credit_limit_bucket, MIN(o.shipping_fee) AS min_shipping_fee, ROUND(AVG(o.discount), 2) AS avg_discount FROM orders o LEFT JOIN customers c ON o.customer_id = c.id LEFT JOIN stores s ON o.store_id = s.id GROUP BY c.is_active, CASE WHEN c.credit_limit >= 16700 THEN 'high' WHEN c.credit_limit >= 2700 THEN 'mid' ELSE 'low' END;
